expressionInfo.expression:
// ======================================================
// RELATED ASSESSOR RECORD
// ======================================================

var rel = FeatureSetByRelationshipName(
    $feature,
    "SDE.PARCELS_DATA_ASSESS",
    [
        "YearID",
        "StreetNumber",
        "StreetName",
        "Owner1",
        "Owner2",
        "BillingAddress",
        "BillingAddress2",
        "City",
        "State",
        "ZipCode",
        "LandUseCode",
        "LegalReference",
        "LegalDescription",
        "SaleDate",
        "SalePrice"
    ],
    false
);

var row = First(rel);


// ======================================================
// PARCEL FEATURE INFORMATION
// ======================================================

var tms = $feature.TMS;
var zone = $feature.Zone;
var plat = $feature.PLAT;
var surveyAcres = $feature["SDE.PARCEL.Area"];


// ======================================================
// PARCEL GEOMETRY
// ======================================================

var parcelAcres = AreaGeodetic(
    $feature,
    "acres"
);

var parcelSqft = Round(
    AreaGeodetic(
        $feature,
        "square-feet"
    ),
    0
);


// ======================================================
// QPUBLIC
// ======================================================

var qpublicURL =
    "https://qpublic.schneidercorp.com/Application.aspx?" +
    "AppID=863" +
    "&LayerID=16169" +
    "&PageTypeID=4" +
    "&PageID=7180" +
    "&Q=1890781294" +
    "&KeyValue=" + Text(tms);

var qpublicLink =
    '<a href="' +
    qpublicURL +
    '" target="_blank">View</a>';


// ======================================================
// IF NO RELATED ASSESSOR RECORD
// ======================================================

if (row == null) {

    return {
        type: "fields",

        fieldInfos: [
            {
                fieldName: "TMS",
                label: "TMS"
            },
            {
                fieldName: "Zone",
                label: "Zone"
            },
            {
                fieldName: "PLAT",
                label: "Plat"
            },
            {
                fieldName: "qPublic",
                label: "qPublic Card"
            },
            {
                fieldName: "ParcelAcres",
                label: "Parcel Polygon (Acres)"
            },
            {
                fieldName: "ParcelSqft",
                label: "Parcel Polygon (Sqft)"
            },
            {
                fieldName: "SurveyAcres",
                label: "Survey Land Area (Acres)"
            }
        ],

        attributes: {
            TMS: tms,
            Zone: zone,
            PLAT: plat,
            qPublic: qpublicLink,

            ParcelAcres: Text(
                parcelAcres,
                "#,###.00"
            ),

            ParcelSqft: Text(
                parcelSqft,
                "#,###"
            ),

            SurveyAcres: IIf(
                IsEmpty(surveyAcres),
                "",
                Text(surveyAcres, "#,###.00")
            )
        }
    };
}


// ======================================================
// COMBINE PROPERTY ADDRESS
// ======================================================

var propertyAddress = "";

if (!IsEmpty(row.StreetNumber)) {
    propertyAddress = Text(row.StreetNumber);
}

if (!IsEmpty(row.StreetName)) {

    if (!IsEmpty(propertyAddress)) {
        propertyAddress += " ";
    }

    propertyAddress += Text(row.StreetName);
}


// ======================================================
// COMBINE OWNERS
// ======================================================

var owner = "";

if (!IsEmpty(row.Owner1)) {
    owner = Text(row.Owner1);
}

if (!IsEmpty(row.Owner2)) {

    if (!IsEmpty(owner)) {
        owner += "<br>";
    }

    owner += Text(row.Owner2);
}


// ======================================================
// COMBINE BILLING ADDRESS
// ======================================================

var billingAddress = "";

if (!IsEmpty(row.BillingAddress)) {
    billingAddress = Text(row.BillingAddress);
}

if (!IsEmpty(row.BillingAddress2)) {

    if (!IsEmpty(billingAddress)) {
        billingAddress += TextFormatting.NewLine;
    }

    billingAddress += Text(row.BillingAddress2);
}


// City, State ZIP
var cityStateZip = "";

if (!IsEmpty(row.City)) {
    cityStateZip = Text(row.City);
}

if (!IsEmpty(row.State)) {

    if (!IsEmpty(cityStateZip)) {
        cityStateZip += ", ";
    }

    cityStateZip += Text(row.State);
}

if (!IsEmpty(row.ZipCode)) {

    if (!IsEmpty(cityStateZip)) {
        cityStateZip += " ";
    }

    cityStateZip += Text(row.ZipCode);
}


// Add City, State ZIP as final billing-address line
if (!IsEmpty(cityStateZip)) {

    if (!IsEmpty(billingAddress)) {
        billingAddress += TextFormatting.NewLine;
    }

    billingAddress += cityStateZip;
}


// ======================================================
// DEED LINK
// ======================================================

var deed = "";

if (!IsEmpty(row.LegalReference)) {

    var deedRef = Text(row.LegalReference);
    var deedParts = Split(deedRef, "-");

    if (Count(deedParts) >= 2) {

        var deedBook = Trim(deedParts[0]);
        var deedPage = Trim(deedParts[1]);

        var deedURL =
            "https://www.georgetowndeeds.com/BookSearch.php?" +
            "book%5Bbookcode%5D=All" +
            "&book%5Bbooknum%5D=" + deedBook +
            "&book%5Bpagenum%5D=" + deedPage +
            "&book%5Bpagesuffix%5D=" +
            "&inst_num=";

        deed =
            '<a href="' +
            deedURL +
            '" target="_blank">' +
            deedRef +
            '</a>';

    } else {
        deed = deedRef;
    }
}


// ======================================================
// FULL POPUP
// ======================================================

return {

    type: "fields",

    fieldInfos: [

        {
            fieldName: "TMS",
            label: "TMS"
        },

        {
            fieldName: "Zone",
            label: "Zone"
        },

        {
            fieldName: "YearID",
            label: "Year"
        },

        {
            fieldName: "PropertyAddress",
            label: "Address"
        },

        {
            fieldName: "Owner",
            label: "Owner"
        },

        {
            fieldName: "BillingAddressCombined",
            label: "Billing Address"
        },

        {
            fieldName: "LandUseCode",
            label: "Current Land Use Code"
        },

        {
            fieldName: "Deed",
            label: "Deed"
        },

        {
            fieldName: "PLAT",
            label: "Plat"
        },

        {
            fieldName: "LegalDescription",
            label: "Legal Description"
        },

        {
            fieldName: "SaleDate",
            label: "Sale Date"
        },

        {
            fieldName: "SalePrice",
            label: "Sale Price"
        },

        {
            fieldName: "qPublic",
            label: "qPublic Card"
        },

        {
            fieldName: "ParcelAcres",
            label: "Parcel Polygon (Acres)"
        },

        {
            fieldName: "ParcelSqft",
            label: "Parcel Polygon (Sqft)"
        },

        {
            fieldName: "SurveyAcres",
            label: "Survey Land Area (Acres)"
        }
    ],

    attributes: {

        TMS: tms,

        Zone: zone,

        YearID: row.YearID,

        PropertyAddress: propertyAddress,

        Owner: owner,

        BillingAddressCombined: billingAddress,

        LandUseCode: row.LandUseCode,

        Deed: deed,

        PLAT: plat,

        LegalDescription: row.LegalDescription,

        SaleDate: IIf(
            IsEmpty(row.SaleDate),
            "",
            Text(
                row.SaleDate,
                "MMMM D, YYYY"
            )
        ),

        SalePrice: IIf(
            IsEmpty(row.SalePrice),
            "",
            Text(
                row.SalePrice,
                "$#,###.00"
            )
        ),

        qPublic: qpublicLink,

        ParcelAcres: Text(
            parcelAcres,
            "#,###.00"
        ),

        ParcelSqft: Text(
            parcelSqft,
            "#,###"
        ),

        SurveyAcres: IIf(
            IsEmpty(surveyAcres),
            "",
            Text(
                surveyAcres,
                "#,###.00"
            )
        )
    }
};

labelExpressionInfo.expression:
var tms = DefaultValue($feature.TMS, "");
var owner = DefaultValue($feature.Owner1, "");

return tms + TextFormatting.NewLine + Left(owner, 25);
